'use strict';
// 基礎系列講義及題庫。Q(題目, [選項…], 正確選項位置（由 0 起計）, 解釋)
const Q = (q, o, a, why) => ({ q, o, a, why });

/* ================= 基礎系列（全體員工） ================= */
const F101 = {
  id: 'F101', name: '公司入職須知', en: 'Company Induction', track: 'F', who: '全體新入職同事', need: [],
  intro: '認識公司的理念、架構、職級及員工守則。所有部門的同事入職後首先修讀本科。',
  material: [
    { h: '一、公司與理念', t: '近觀者新聞有限公司（Close Viewer News Corporation）是一間在 Discord 模擬社會內運作的新聞機構。\n\n公司口號是**「看得近，報得真。」**：記者走到事實跟前，看清楚，才下筆。\n\n公司理念是**「接近事實的觀點」**。我們不假裝沒有立場，但任何觀點都必須建基於查證過的事實。因此本公司的稿件只有兩類：\n• **新聞**：只寫查證到的事實，誰說的就寫明是誰說的。\n• **評論**：可以有觀點，但必須標明【評論】，而且所依據的事實必須正確。\n\n兩者永遠分開，不會混在同一篇稿內。' },
    { h: '二、公司架構', t: '公司由董事會領導，下設七個部門：\n\n**新聞部**：採訪、跟進報料、撰寫新聞稿及專題。\n**編輯部**：審稿、事實查核、決定發佈、發出更正。\n**製作部**：新聞圖片、圖表、版面及影片製作。\n**客戶及市務部**：處理查詢及合作個案、管理客戶名冊、拓展讀者。\n**人力資源及行政部**：招聘、入職、培訓、晉升、申請審批及紀律事宜。\n**資訊科技部**：維護系統、網站及資料安全。\n**合規部**：處理投訴及更正要求、內部審核、監察守則執行。\n\n最重要的一條界線：**編採獨立**。客戶、贊助人、合作夥伴及任何同事的私人關係，都不能換取一篇報道，也不能抽起一篇報道。稿件能否發佈，只由編輯部按事實決定。' },
    { h: '三、職級與職銜', t: '公司設九個職級，分為三層：\n\n**員工**：第 1 級 見習職員、第 2 級 職員、第 3 級 高級職員\n**管理人員**：第 4 級 助理經理、第 5 級 經理、第 6 級 總監\n**高層管理及董事會**：第 7 級 總經理、第 8 級 執行董事、第 9 級 董事會主席\n\n**第 1 至 3 級的職銜是職位。** 新聞部是記者（見習記者、記者、高級記者），編輯部是編輯，製作部是製作員，客戶及市務部是客戶主任，人力資源及行政部是人事主任，資訊科技部是系統主任，合規部是合規主任。\n\n**第 4 至 6 級的職銜是「部門職能＋管理職級」。** 例如新聞部第 4 級是「助理新聞經理」（Assistant Press Manager），人力資源及行政部第 5 級是「人力資源經理」。\n\n第 1 至 4 級按公開條件晉升：通過試用期評核、取得所需證書、入職日數達標、表現評核達標、紀律良好；新聞部另計已發佈稿件數目。條件齊備後由系統核對，不靠關係。第 5 級或以上屬委任職位，由董事會決定。\n\n使用 `/profile` 可以隨時查看自己距離下一級尚欠甚麼。' },
    { h: '四、員工守則', t: '**一、申報利益。** 工作涉及你本人、你的朋友或你在模擬社會內所屬的組織，必須向上司申報，並交由其他同事處理。\n**二、保密。** 未發佈的稿件、消息來源的身份、人事紀錄、客戶資料及內部討論，一律不得外洩。\n**三、不收受利益。** 不得因為工作而收受遊戲幣、道具、身份組或任何好處。\n**四、表明身份。** 代表公司工作時，須表明自己是近觀者的員工及職銜，不得冒充他人。\n**五、出錯即報。** 發現自己或同事出錯，第一時間通知上司。隱瞞錯誤比犯錯嚴重得多。\n**六、互相尊重。** 對同事、受訪者及公眾保持禮貌。意見不合可以討論，不可以人身攻擊。\n**七、只處理模擬世界。** 不收集、不公開任何人的現實個人資料。\n**八、考核必須獨立完成。** 考試及文章須由本人完成，不得使用人工智能工具代答或代寫，亦不得抄襲講義或他人的答案。違者成績作廢，並按紀律程序處理。' },
    { h: '五、入職第一個星期', t: '1. 修畢 **F101、F102、F103** 三科，取得《基礎專業證書》。這是晉升為職員（第 2 級）的必要條件。\n2. 到「員工服務」頻道認識各項自助服務：員工檔案、值勤、申請、學院。\n3. 開始工作前按「開始值勤」，完成後按「結束值勤」並寫下工作摘要。\n4. 找到你的直屬上司（部門的助理經理或經理），確認第一項工作。\n5. 有不明白的地方，到「新人問答」頻道發問，沒有問題是不應該問的。\n\n使用 `/help` 可以按你的職級列出可用的指令。' },
  ],
  q: [
    Q('公司理念「接近事實的觀點」的意思是：', ['記者可以隨意表達立場', '觀點可以有，但必須建基於查證過的事實', '只報道官方公佈的消息', '不可以發表任何評論'], 1, '本公司容許評論，但評論必須標明，而且所依據的事實必須正確。'),
    Q('一篇稿同時有查證過的事實及記者個人的看法，應如何處理？', ['照樣發佈，讀者自會分辨', '事實寫成新聞，看法另寫成標明【評論】的文章', '把看法寫成「有市民認為」', '刪去事實，只留看法'], 1, '新聞與評論永遠分開。把個人看法假託為「有市民認為」屬於造假。'),
    Q('一位合作夥伴要求抽起一篇關於他的報道，客戶及市務部的同事應該：', ['答應，以免影響合作', '說明編採獨立，並把意見轉交編輯部按事實處理', '自行修改稿件', '要求記者道歉'], 1, '編採獨立是公司最重要的界線。報道有沒有錯，由編輯部按事實判斷。'),
    Q('新聞部第 4 級的職銜是：', ['記者', '高級記者', '助理新聞經理', '新聞總監'], 2, '第 4 級是助理經理；加上部門職能「新聞」，即助理新聞經理（Assistant Press Manager）。'),
    Q('以下哪一個職級屬於委任職位，不能單靠達標晉升？', ['職員', '高級職員', '助理經理', '經理'], 3, '第 1 至 4 級按公開條件晉升；第 5 級（經理）或以上由董事會委任。'),
    Q('你在模擬社會內是某機構的成員，今天收到一宗關於該機構的工作，你應該：', ['自己處理，因為你最熟悉', '向上司申報，並交由其他同事處理', '不作處理，也不告訴任何人', '先通知該機構的朋友'], 1, '這是利益衝突，必須申報並避席。通知被報道的一方更屬洩密。'),
    Q('你發現自己昨天提交的資料有錯，但暫時無人察覺。應該：', ['悄悄改好就算', '第一時間通知上司', '等有人發現才處理', '請同事代為承擔'], 1, '出錯即報。隱瞞錯誤比犯錯嚴重得多。'),
    Q('有讀者送你遊戲道具，感謝你寫了一篇對他有利的報道。你應該：', ['收下，反正稿已發佈', '婉拒，並告知上司', '收下後轉送同事', '要求他多送一些'], 1, '不得因工作收受任何利益，事後答謝亦不例外。'),
    Q('由見習職員晉升為職員（第 2 級）必須取得哪一張證書？', ['管理人員證書', '基礎專業證書', '資訊保安證書', '不需要任何證書'], 1, '《基礎專業證書》由 F101、F102、F103 三科組成，是晉升職員的必要條件。'),
    Q('以下哪一項屬於合規部的職責？', ['撰寫新聞稿', '處理投訴及更正要求', '製作新聞圖片', '維護網站'], 1, '合規部負責投訴、更正要求、內部審核及監察守則執行。'),
  ],
};

const F102 = {
  id: 'F102', name: '工作流程及系統', en: 'Workflow and Systems', track: 'F', who: '全體同事', need: ['F101'],
  intro: '一件工作由接收到完成應該怎樣走；頻道標記、值勤、交接、申請及上報的做法。',
  material: [
    { h: '一、一件工作的生命周期', t: '公司內每一件工作都經過同樣的六步：\n\n**接收 → 認領 → 處理 → 覆核 → 完成 → 記錄**\n\n• **接收**：工作以編號識別。稿件是 CV-0001，申請是 REQ-0001，客戶個案是 CS-0001。談論工作時請引用編號。\n• **認領**：每件工作只有一位負責人。按下「跟進」或「接手處理」，其他同事就知道這件事有人負責。\n• **處理**：在期限內完成；做不到要提早說。\n• **覆核**：重要的工作必須由第二個人看過，例如稿件要由編輯審批，申請要由上司審批。任何人都不可以覆核自己的工作。\n• **完成**：通知有關的人，並說明結果。\n• **記錄**：系統會自動寫入紀錄頻道。\n\n原則：**沒有紀錄的工作，等於沒有做過；沒有負責人的工作，等於沒有人做。**' },
    { h: '二、頻道與標記', t: '伺服器內的頻道名稱只使用四個公司標記，看標記就知道頻道的用途：\n\n**◈ 正式發佈**：公告、新聞、通告。只有系統或管理層發言，內容代表公司。\n**◆ 工作台**：有按鈕或待辦事項的頻道，例如服務台、審稿台、申請審批。在這裡處理工作，不在這裡閒談。\n**◇ 討論**：同事或公眾交流的地方，例如員工大堂、各部門頻道。\n**▤ 紀錄**：系統自動記錄，任何人都不可發言，例如人事紀錄、編採紀錄。\n\n規則很簡單：**工作在工作台做，討論在討論頻道談，決定要回到工作台落實。** 在討論頻道達成的口頭共識，如果沒有在系統內落實（例如按下批准），就不算數。' },
    { h: '三、值勤與交接', t: '**值勤**\n開始工作時，在「員工服務」按「開始值勤」（或使用 `/duty on`）；完成後按「結束值勤」，並用一兩句寫下這段時間完成了甚麼。值勤時數會記入員工檔案，是上司了解工作量的依據。\n\n忘記結束值勤，系統會在十二小時後自動結束並標記為逾時。\n\n**交接**\n工作未完成而你要離開，必須交接。一個合格的交接只需要三句：\n1. **已完成**：我做了甚麼。\n2. **未完成**：還有甚麼未做，卡在哪裡。\n3. **下一步**：誰接手，何時之前要完成。\n\n例：「CS-0012 已回覆客戶並取得截圖；尚未核對原訊息；請陳主任明天中午前核對後結案。」\n\n交接寫在該項工作的討論串或部門頻道，不要只用私訊，否則其他同事無從得知。' },
    { h: '四、申請與審批', t: '需要公司批准的事情，一律經「員工服務」的「提交申請」辦理，不以私訊口頭提出。申請類別包括：\n\n• **請假**：寫明日期、原因及工作交接安排。\n• **資源或器材**：需要甚麼、用途、何時需要。\n• **經費或報銷**：金額、用途及單據。\n• **權限開通**：需要哪個頻道或系統的權限及原因。\n• **調職**：希望調往的部門及理由。\n• **離職通知**：最後工作日及交接安排。\n\n**審批規則**\n• 由申請人所屬部門的助理經理或以上，或人力資源及行政部的助理經理或以上審批。\n• 任何人不可審批自己的申請。\n• 審批人應在 48 小時內處理；不批准必須寫明原因。\n• 結果會以私訊通知申請人，並寫入申請紀錄。\n\n請假應盡量提前申請。事後補假只限突發情況。' },
    { h: '五、上報', t: '上報不是推卸責任，而是把決定交給有權限的人。以下情況必須上報：\n\n• 事情**超出你的權限**（例如你無權批准，或無權對外承諾）。\n• 你有**利益衝突**。\n• 涉及**安全、私隱或聲譽風險**（例如有人威脅同事、疑似資料外洩）。\n• **超過期限**仍未能解決。\n\n**向誰上報**：直屬上司 → 部門經理 → 部門總監 → 董事會。除非上司本人就是問題所在，否則不要越級。\n\n**怎樣上報**：用三句說清楚。\n1. 發生了甚麼事（事實，附編號或連結）。\n2. 我已經做了甚麼。\n3. 我需要你決定甚麼，何時之前。\n\n上報之後，事情仍然由你跟進，直至上司明確表示由他接手。' },
  ],
  q: [
    Q('公司內一件工作的六個步驟，正確次序是：', ['處理 → 接收 → 完成 → 記錄 → 認領 → 覆核', '接收 → 認領 → 處理 → 覆核 → 完成 → 記錄', '認領 → 接收 → 覆核 → 處理 → 記錄 → 完成', '接收 → 處理 → 完成'], 1, '接收、認領、處理、覆核、完成、記錄。'),
    Q('報料箱有一宗新報料，你打算跟進。第一步應該：', ['直接開始採訪', '按「跟進」認領，讓其他同事知道已有人負責', '在員工大堂說一聲', '等上司指派'], 1, '每件工作只有一位負責人。先認領，避免兩個人重複做，或大家都以為有人做。'),
    Q('頻道名稱以「◆」開頭，代表：', ['正式發佈，只有管理層發言', '工作台，在這裡處理工作', '討論頻道', '系統紀錄'], 1, '◈ 正式發佈、◆ 工作台、◇ 討論、▤ 紀錄。'),
    Q('幾位同事在討論頻道同意批准某項申請，但沒有人在系統按下批准。這項申請：', ['已經批准', '尚未批准，須在系統內落實才算', '自動批准', '已被拒絕'], 1, '決定要回到工作台落實。沒有紀錄等於沒有做過。'),
    Q('以下哪一個交接寫得最好？', ['我先下線，餘下的拜託大家。', 'CS-0012 已回覆客戶；尚未核對原訊息；請陳主任明天中午前核對後結案。', '那個個案差不多完成。', '有事私訊我。'], 1, '合格的交接有三樣：已完成、未完成、下一步由誰何時之前完成。'),
    Q('你想請假三天，正確做法是：', ['私訊上司說一聲', '在「員工服務」提交請假申請，寫明日期、原因及交接安排', '直接不上線', '在員工大堂公佈'], 1, '需要批准的事情一律經申請系統辦理，才有紀錄。'),
    Q('誰可以審批你的請假申請？', ['你自己', '同級的同事', '你所屬部門的助理經理或以上，或人力資源及行政部的助理經理或以上', '任何員工'], 2, '任何人都不可以審批自己的申請。'),
    Q('以下哪一種情況必須上報？', ['工作順利完成', '有人威脅要對付你的同事', '同事請你吃飯', '你想更換頭像'], 1, '涉及安全、私隱或聲譽風險的事情必須上報。'),
    Q('向上司上報時，最重要的是說清楚：', ['你有多辛苦', '發生了甚麼、你已做了甚麼、你需要對方決定甚麼', '誰應該負責', '你的感受'], 1, '三句：事實、已採取的行動、需要的決定及期限。'),
    Q('你忘記結束值勤便下線。系統會：', ['一直計算時數', '在十二小時後自動結束並標記為逾時', '刪除你的值勤紀錄', '自動請假'], 1, '逾時的值勤會被標記，上司會看到。請養成結束值勤並寫下摘要的習慣。'),
  ],
};

const F103 = {
  id: 'F103', name: '專業溝通', en: 'Professional Communication', track: 'F', who: '全體同事', need: ['F101'],
  intro: '怎樣寫清楚的工作訊息、提問、開會、給予意見，以及代表公司對外溝通。',
  material: [
    { h: '一、寫清楚的工作訊息', t: '同事每天收到大量訊息。一個好的工作訊息，對方讀一次就知道要做甚麼。\n\n**四個原則**\n1. **結論先行**：第一句就說重點或你的要求，背景放在後面。\n2. **一個訊息一件事**：兩件不相關的事分開發。\n3. **寫明行動**：需要對方做甚麼、何時之前。\n4. **附上編號或連結**：讓對方不必再問「哪一篇」。\n\n**對比**\n不佳：「你好，想問一下，之前那篇稿，就是上星期那篇，好像有點問題，你有空可以看看嗎？」\n較佳：「請在今晚八時前覆核 CV-0031 第二段的數字。來源文件寫 120 人，稿件寫 210 人。」\n\n不要只發一句「在嗎？」然後等待。把事情一次說完，對方有空便可直接回覆。' },
    { h: '二、提問與回覆', t: '**提問之前**：先查。使用 `/help`、公司手冊、頻道置頂訊息，很多答案已經寫好。\n\n**提問時**給足三樣資料：\n• 你想做到甚麼；\n• 你已經試過甚麼；\n• 卡在哪一步（附截圖或錯誤訊息）。\n\n**回覆的規矩**\n• 工作訊息在 **24 小時內回覆**。未能即時處理，也先回一句：「已收到，星期三前回覆。」\n• 承諾了時間就要做到；做不到，在期限前說明，並給新的時間。\n• 回覆要回到原本的討論串，方便日後查閱。\n\n沉默是最差的回覆：對方不知道你是沒看到、正在處理，還是不同意。' },
    { h: '三、會議', t: '會議佔用所有出席者的時間，所以要開得有結果。\n\n**會前**：召集人發出議程，列明要討論的事項及需要作出的決定。沒有議程的會議可以不開。\n**會中**：只討論議程上的事項。每個事項結束時，召集人複述結論。\n**會後**：24 小時內發出會議紀錄，只需三欄：\n\n**決定**｜**負責人**｜**期限**\n\n例：「新聞頻道每晚九時發佈當日摘要｜李經理｜下星期一開始」\n\n沒有負責人及期限的「共識」，通常不會有人執行。\n\n如果一件事可以用一則清楚的訊息解決，就不需要開會。' },
    { h: '四、給予及接受意見', t: '**給予意見**\n• **對事不對人**：說稿件、說做法，不評價人。\n• **具體**：指出哪一處、為甚麼、可以怎樣改。\n• **及時**：事情發生後盡快提出，不要累積。\n• **私下指正，公開讚賞。**\n\n不佳：「你寫得很差，重寫。」\n較佳：「第二段寫『多名市民不滿』，但來源只有一位。請補兩位受訪者，或改為『一名市民』。」\n\n**接受意見**\n• 先聽完，確認自己理解：「你的意思是第二段的來源不足，對嗎？」\n• 不同意可以說明理由，但不要即時反駁或辯解。\n• 改好之後告訴對方。\n\n意見是針對工作的，不是針對你。' },
    { h: '五、對外溝通', t: '你在公眾頻道或其他伺服器的言行，別人會視為公司的立場。\n\n• **誰可以代表公司發言**：正式立場只由獲授權的同事（總監或以上，或其指定的人）發表。其他同事被問及公司立場時，回答：「我會把你的問題轉交負責的同事。」\n• **未發佈的內容**：一律回答「暫時未能提供資料」，不確認也不否認。\n• **不承諾權限以外的事**：例如不可以答應對方「一定會報道」或「一定會更正」。可以說：「我會把個案交給編輯部，他們會在 24 小時內回覆你。」\n• **保持禮貌及準確**：即使對方態度惡劣。\n• **爭執不公開進行**：有人在公眾頻道指責公司，請對方到服務台開立個案，並通知上司，不要在公眾頻道爭辯。' },
  ],
  q: [
    Q('以下哪一則工作訊息寫得最好？', ['在嗎？', '那篇稿好像有問題，你有空看看。', '請在今晚八時前覆核 CV-0031 第二段的數字：來源寫 120 人，稿件寫 210 人。', '有事找你，很急。'], 2, '結論先行、寫明行動及期限、附上編號。'),
    Q('收到一則工作訊息，但你要兩天後才能處理。應該：', ['兩天後才回覆', '先回覆「已收到，星期三前回覆」', '已讀不回', '請對方找別人'], 1, '24 小時內回覆；未能處理也先確認收到並給時間。'),
    Q('提問之前應該先做甚麼？', ['直接私訊總監', '先查 /help、公司手冊及置頂訊息', '在所有頻道各問一次', '等別人發問'], 1, '先查再問，可以節省雙方的時間。'),
    Q('一份合格的會議紀錄，最少要有：', ['每個人說過的每一句話', '決定、負責人、期限', '出席者的心情', '會議時間長度'], 1, '沒有負責人及期限的共識通常不會被執行。'),
    Q('同事的稿件來源不足。哪一句意見最恰當？', ['你寫得很差。', '下次用心一點。', '第二段寫「多名市民不滿」，但來源只有一位，請補充或改為「一名市民」。', '我不想再看你的稿。'], 2, '對事不對人、具體、指出可以怎樣改。'),
    Q('上司指出你的工作有問題，而你並不同意。應該：', ['即時反駁', '先確認理解對方的意思，再說明你的理由', '不作回應', '向其他同事抱怨'], 1, '先聽完並確認理解，不同意可以說明理由。'),
    Q('有公眾問你一篇尚未發佈的報道內容，你應該回答：', ['把內容告訴他', '「暫時未能提供資料。」', '「我們沒有這篇稿。」', '「明天就會發佈。」'], 1, '未發佈的內容不確認也不否認。'),
    Q('有人在公眾頻道指責公司報道失實。你（主任級）應該：', ['在公眾頻道與他爭辯', '請對方到服務台開立個案，並通知上司', '刪除他的訊息', '嘲諷他'], 1, '爭執不公開進行；交由正式途徑處理並上報。'),
    Q('一位讀者要求你保證他的投訴「一定會獲得更正」。你應該：', ['答應他', '說明你會把個案交給負責部門，並告知回覆時限', '叫他不要投訴', '不回覆'], 1, '不承諾權限以外的事，但要說明下一步及時間。'),
    Q('以下哪一種情況最適合開會？', ['通知大家一項已經決定的安排', '需要幾個部門一起作出決定的事項', '問一位同事一個簡單問題', '分享一條連結'], 1, '可以用一則清楚訊息解決的事不必開會。'),
  ],
};
module.exports = [F101, F102, F103];
